const clone = (x: Preset): Preset => ({ ...x, params: x.params.map((q) => ({ ...q })) });

/** Every preset, in catalogue order. */
export function listPresets(): Preset[] {
  return PRESETS.map(clone);
}

export function getPreset(id: string): Preset | null {
  const f = PRESETS.find((x) => x.id === id);
  return f ? clone(f) : null;
}

export const PRESET_IDS: readonly string[] = PRESETS.map((x) => x.id);
